ALTER TABLE public.orc_integracao_config ADD CONSTRAINT orc_config_unica CHECK(id=true);
ALTER TABLE public.orc_projeto_budget ADD CONSTRAINT orc_budget_finito CHECK(budget_liberado IS NULL OR (budget_liberado>=0 AND budget_liberado::text NOT IN ('NaN','Infinity','-Infinity')));
ALTER TABLE public.orc_realizado_espelho ADD CONSTRAINT orc_valores_finitos CHECK(realizado::text NOT IN ('NaN','Infinity','-Infinity') AND (orcado IS NULL OR orcado::text NOT IN ('NaN','Infinity','-Infinity')));
CREATE FUNCTION public.orc_lote_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.centro_custo)>200 OR nullif(btrim(NEW.centro_custo),'') IS NULL OR NEW.competencia !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' THEN RAISE EXCEPTION 'Centro/competência inválido'; END IF; RETURN NEW; END $$;
CREATE TRIGGER orc_lote_guard BEFORE INSERT OR UPDATE ON public.orc_realizado_espelho FOR EACH ROW EXECUTE FUNCTION public.orc_lote_guard();
CREATE OR REPLACE FUNCTION public.orc_importar(_itens jsonb,_arquivo text,_modo text DEFAULT 'planilha') RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; n integer:=0; lid uuid; BEGIN IF _modo IS NULL OR _modo NOT IN ('api','planilha') OR _itens IS NULL OR jsonb_typeof(_itens)<>'array' OR jsonb_array_length(_itens)>10000 THEN RAISE EXCEPTION 'Lote inválido (máximo 10000)'; END IF; IF NOT public.orc_pode_ler() OR (_modo='planilha' AND NOT public.mt_is_governanca(auth.uid())) OR (_modo='api' AND NOT public.proj_gov_ou_ceo(auth.uid())) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _modo='api' AND NOT EXISTS(SELECT 1 FROM orc_integracao_config WHERE id=true AND ativo) THEN RAISE EXCEPTION 'Integração desligada'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_array_elements(_itens) x GROUP BY btrim(x->>'centro_custo'),x->>'competencia' HAVING count(*)>1) THEN RAISE EXCEPTION 'Centro/competência duplicado'; END IF;
FOR e IN SELECT value FROM jsonb_array_elements(_itens) LOOP IF jsonb_typeof(e)<>'object' OR coalesce(jsonb_typeof(e->'centro_custo'),'null')<>'string' OR nullif(btrim(e->>'centro_custo'),'') IS NULL OR length(e->>'centro_custo')>200 OR coalesce(e->>'competencia','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' OR coalesce(jsonb_typeof(e->'realizado'),'null')<>'number' OR (e ? 'orcado' AND jsonb_typeof(e->'orcado') NOT IN ('number','null')) THEN RAISE EXCEPTION 'Linha inválida'; END IF; END LOOP;
INSERT INTO orc_sync_log(modo,ok,usuario_id,arquivo) VALUES(_modo,false,auth.uid(),left(_arquivo,255)) RETURNING id INTO lid;
FOR e IN SELECT value FROM jsonb_array_elements(_itens) LOOP INSERT INTO orc_realizado_espelho(centro_custo,competencia,realizado,orcado,origem) VALUES(btrim(e->>'centro_custo'),e->>'competencia',(e->>'realizado')::numeric,nullif(e->>'orcado','')::numeric,_modo) ON CONFLICT(centro_custo,competencia) DO UPDATE SET realizado=excluded.realizado,orcado=excluded.orcado,origem=excluded.origem,sincronizado_em=now(); n:=n+1; END LOOP; UPDATE orc_sync_log SET ok=true,registros=n,concluido_em=now() WHERE id=lid; RETURN n; END $$;
CREATE FUNCTION public.orc_registrar_falha(_modo text,_mensagem text,_arquivo text DEFAULT null) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.orc_pode_ler() OR NOT public.proj_gov_ou_ceo(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; INSERT INTO orc_sync_log(modo,mensagem,arquivo,usuario_id,concluido_em) VALUES(left(_modo,20),left(_mensagem,200),left(_arquivo,255),auth.uid(),now()); END $$;
REVOKE ALL ON FUNCTION public.orc_registrar_falha(text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.orc_registrar_falha(text,text,text) TO authenticated;